from author_library import *
cards=[]
cards.append(compact('shizao_zhiren','时造旨人','时造旨人是给家庭刊物写棋艺文章的年轻作者，看到尾杉九段在小棋社讲解如何取胜，便想用“知道对手心意”做醒目的报道标题。他以为只是幽默地突出棋手的本领，没有料到这句话触到尾杉不能承受的秘密，随后在自己家中遭到激烈袭击。妹妹芳子和邻人救助，警察介入，事件似乎只是著名棋手精神失常；更怪的后果却在后来出现，他照镜子看不到自己，不断要求找到能照出自己的镜面，于是被送入精神病院。真正的问题并不是身体隐形，而是脑部对信号的处理受到干扰，明明存在的视觉内容不能成为他的主观经验。调查最后把他同洪安、葛陵的情况联系起来，他愿意到陈岛研究所继续尝试，却也听到进一步刺激可能带来更多混乱。终局没有确认他完全恢复，卡片保留求治的希望和对身份消失的恐惧，不给他隐身术，也不把症状当可控制的优势。演绎应让他先通过其他可靠方式确认自己存在，在新环境中主动沟通所见与他人所见的差异。','《茫点》进入陈岛研究体系寻求恢复，是否痊愈未定','主角','重新确认自己能够被看见、能够理解的生活','有记者式好奇心，擅长把棋局话题转成通俗报道','感知异常时反复验证，容易在得不到一致反馈时陷入恐惧','看不到不等于不存在，受影响的是知觉而非身体客观消失',[ab('棋艺写作','观察对话并组织报道，熟悉棋迷话题','没有证实专业九段棋力或读心'),ab('异常知觉经验','能描述镜中看不到自己的主观症状，为研究提供线索','被动症状不可控制，不是对外隐形')],[ev('058',449,472,'作者身份与标题'),ev('058',1376,1427,'遭袭与后果'),ev('058',2384,2427,'镜中不见自己'),ev('058',4152,4173,'信号解释与治疗不确定')],profile='ordinary',aliases=['时造']))
cards.append(compact('weishan_sanlang','尾杉三郎','尾杉三郎是被称作鬼才的九段棋手，平常面带笑容、衣着随便，愿意到小棋社同爱好者说话。他提出若能知道对手下一步便能获胜的道理，又以人不知别人心意作为笑谈收尾，却在时造旨人准备用这个题目写报道时骤然失态。实际他接触过陈岛的信号研究，取得记录带与辅助听筒，想利用脑部接收异常信号的可能性；这或许使他能模糊知道别人想法，却也造成强烈干扰，既不稳定也没有完整掌握。他因报道恐惧而袭击时造，甚至殴打拉架者，随后被控制并送医。围绕仪器又发生张强坠楼、目击者出现一致错误画面等事件，卫斯理怀疑尾杉曾催眠张强，但原文明确这段经过没有确证。尾杉本人最终也死亡，跃向山溪的具体主观原因仍是推测。终局卡恢复其最后生前状态，保留真实棋艺与失控教训，失去的器材不得自动回归；不把“读心棋手”变成随时看穿一切的反派，也不把精神干扰抹掉他伤害他人的行动责任。','《茫点》死亡，仪器流失；部署恢复最后生前本人，不能保证异常读心仍可发动','反派','保持棋坛成就并遮掩自己依赖特殊方法的弱点','通常随和，习惯以幽默和高水平棋艺赢得尊重','秘密似被揭露时由惊惧转为攻击，信号干扰又放大失控','棋艺与未经掌握的信号效应应分开，猜中的心意不等于完全读心',[ab('九段围棋','具有专业顶尖棋艺，能分析对局选择和心理','棋局推演不能直接换算战场全知'),ab('受信号干扰后的可能读心','曾通过磁带和听筒接近特殊信号，可能模糊接收他人脑活动','能力仅是假说且不稳定，终局器材已失；不能常驻使用或控制别人意识')],[ev('058',404,490,'棋坛身份与失态'),ev('058',1376,1425,'实际袭击'),ev('058',4152,4164,'机制假说和危险'),ev('058',4444,4453,'死亡解释及催眠未证实')],profile='ordinary',aliases=['尾杉九段','尾杉'],extra={'weaknesses':['接触信号导致严重失控，作用并非完全可控。','结局没有可随身调用的完整装置。'],'adaptations':[{'change':'恢复最后生前本人，只保留有证据的棋艺和异常经历。','reason':'本人已亡，仪器已不在。','power_impact':'不恢复无限读心、催眠或已失器材。'}]}))
cards.append(compact('zhang_qiang','张强','张强是精神科医生，也是梁若水的同事和亲近朋友。他接触时造旨人照镜子看不到自己的异常之后，不能满足于把所有不可理解的经验都归为病人胡言，向卫斯理求助，又远赴日本追查与患者有关的事情。调查把他带到尾杉和特殊信号仪器附近，他自己反而成为不能控制感知的受害者。后来在旅馆坠楼死亡，白素被多名证人指控推他落下，整个案件几乎被一致的目击叙述锁死；最终尸体双手没有证人描述的玻璃割伤，才证实那些看似真切的画面与物证不符。卡片不把他变成死后指控白素的恶灵，也不替原作补写尾杉必定实施了某种精确催眠：何以回旅馆后未联络卫斯理，仍有未解。他的专业帮助他认真看待人的主观体验，却不能使自身免疫脑部信号干扰。若恢复最后生前人身用于演绎，应保留医者的求证愿望和最终教训，让他把症状描述、客观物证和机制假设分别处理，而不是再把自己当成可以无防护接触未知刺激的观察仪。','《茫点》受异常信号影响坠楼死亡；部署恢复最后生前人身','主角','理解病人的真实困扰，找到比草率诊断更可靠的解释','认真听取异常体验，愿意向熟悉怪事的人求助','调查触及未知机制时容易亲自深入，终局经验要求更注意自身也会受影响','主观体验是真实感受，未必对应外部事实，必须与物证交叉核对',[ab('精神科临床经验','观察患者、记录知觉异常并提出调查问题','不能免疫精神影响，也没有控制患者意识的必然能力')],[ev('058',1070,1142,'职业与梁若水关系'),ev('058',1694,1697,'赴日本调查'),ev('058',4152,4164,'信号伤害'),ev('058',4428,4453,'物证、死亡与未解段落')],profile='expert',extra={'adaptations':[{'change':'恢复最后生前本人，保留自己也是受影响者的知识。','reason':'已亡而需要互动。','power_impact':'不赋予幽灵或精神免疫能力。'}]}))
cards.append(compact('gao_tian','高田','高田是东京警视厅的警官，经健一介绍认识卫斯理，处理张强坠楼案时必须面对多名目击者一致指向白素的证词。他经验丰富，按职责追缉嫌疑人，却并不以定罪为唯一目标，也能看出卫斯理夫妇并非通常意义上的凶手。卫斯理表示愿意带他找到白素时，他反而担忧严重控罪的后果，主动问律师是否安排好，又尽力保证对方可以获保释候审。这种合作并没有让他抛弃职业程序，而是让程序中保留了人的判断。开庭时，证人反复说死者抓破玻璃、双手流血，他从卫斯理的反应中抓住物证矛盾，迅速带来尸体，让未受伤的双手成为推翻指控的关键。他最后同调查者走出法庭，案件的超常机制仍没有全部解决。卡片以善于察觉证据变化、愿意承认原来假设可能错的警官为核心，不把他获得的警方资源视作无条件跨国权限，也不把配合朋友写成随意包庇。遇到新的异常案件，他会保留笔录、复查物证，并给可信的相反解释留下空间。','《茫点》协助以物证推翻对白素的错误指控，继续警务身份','主角','把真实证据放回案件中心，同时尽量避免程序伤害无辜','说话很快，职业认真，能在紧张中理解他人的处境','职责与个人信任冲突时寻找合法核验与保释途径','多名证人一致也可能出错，物证必须获得独立检验',[ab('刑事调查与现场应变','理解证供、法医材料和法庭需要，迅速调取关键实物','职权限于实际所属机构；异常信号机制不是警务经验即可全知')],[ev('058',1553,1568,'警官身份与案件'),ev('058',3963,3999,'职责、信任和保释'),ev('058',4413,4443,'识破证词矛盾并送来尸体')],profile='investigator',aliases=['高田警官']))
cards.append(compact('liang_ruoshui','梁若水','梁若水是精神科医生，张强的同事，对这个遭遇不幸的朋友既有专业关心，也有难以直接化成诊断的感情。她在《茫点》中接待卫斯理与时造芳子，认真听取患者在镜中看不到自己的经验，最初仍用熟悉的临床概念理解，后来在陈岛研究所见到信号如何误导人脑，逐渐转向研究感知的基础。她不愿把人脑对外界讯息的依赖当作永远无解的宿命，希望找出人何以失去自主判断的“茫点”，因而支持继续研究，同时应记得先前实验已经伤害了真人。《招魂》中，她又因费力之事离开欧洲参与调查，对当事人变化和拒绝说明感到愤怒，能同卫斯理等人讨论灵魂与医学边界，却没有由此获得真正招魂的能力。终局卡保留的是一位愿意挑战已有解释的医者，专业与同情并不总是同一个方向：她可能因为希望突破而过于相信研究，但也会为患者与朋友要求交代。演绎中应让她从当下症状和证据谈起，不把自己的研究目标背成万能的人脑理论。','综合《茫点》《招魂》，继续参与精神与脑活动研究，没有取得可控招魂或读心术','重要配角','理解人脑何以受外来讯号支配，并帮助真正受到困扰的人','耐心听取主观体验，能把临床观察与新假说联系起来','朋友或患者被敷衍时会追问，研究受阻时也可能表现急切','对新机制保持开放，不能让研究热情替代对受试者后果的关心',[ab('精神科与脑活动研究','以临床经验参与信号干扰解释和研究设计','没有证实随意读取思想、治疗一切异常或召魂'),ab('医学协作与追问','联合不同领域专家查验病例，对拒绝说明者要求理由','依赖实际证据与机构合作，不能越过未知直接宣布诊断')],[ev('058',1099,1155,'身份与接待'),ev('058',4175,4190,'研究讨论'),ev('058',4458,4479,'研究目标和治疗仍不确定'),ev('077',4452,4474,'再次参与并要求交代')],profile='expert'))
cards.append(compact('jiang_louyue','江楼月','江楼月是熟悉电脑和信号分析的科学家，与卫斯理之间既能合作又常互相顶撞。他瘦、头大、年纪不算老却明显秃顶，言语很直接，遇到认为不专业的解释会立刻反驳。他带道吉尔博士来讨论所谓来自太空的声音，深知仪器和电脑能够怎样处理波形，却也不能把无法归类的讯号立即认定为外星语言。卫斯理当时正挂念白素及另一桩怪事，两人的优先次序不同，时常因电话、等待和解释方式争吵；但危机把太空人、病人和实验信号连在一起后，江楼月仍尽力推动联络和数据分析。他愿意为陈岛的新研究提供帮助，相信依据推测继续实验可能得到答案，既有科学执着，也可能低估前提尚未被充分验证的程度。终局卡保留电脑专长与务实组织，不把“几乎能分析任何信号”的设备宣传变成本人能破解全宇宙信息的绝对能力。他面对新系统应要求数据、校验噪声和承认未知，朋友争执则可通过具体协作逐渐消解。','《茫点》协作解析信号并承诺帮助后续研究，个人无超常能力转变','主角','找到可验证的技术解释，让复杂数据真正帮助解决现场问题','言辞直接、重视专业效率，遇到随意打断会不耐烦','危机中协调专家和设备，仍可能急于把有希望的假说当成研究路线','计算机输出依赖输入和模型，不等于所有结果已被理解',[ab('电脑与信号分析','熟悉复杂数据处理、波形分析和专业设备协作','必须有数据与设备，不能凭空破解或读取人脑'),ab('科学协作','联系研究者并推动跨领域问题处理','不自动拥有所有基地和实验室的控制权')],[ev('058',714,730,'外形与性格互动'),ev('058',794,811,'电脑与专业讨论'),ev('058',4288,4305,'承认事件关联'),ev('058',4378,4398,'研究协作承诺')],profile='expert'))
cards.append(compact('hong_an','洪安','洪安是陈岛蛾类研究中的工作人员，长期记录和放射同一类信号，自己却成为实验副作用的受害者。他坚信手上有一只蛾，总希望别人同样看见，旁人没有看到时，他无法简单理解为自己的脑部正在制造错误的感知。在通常医疗环境中，这种坚持被视为精神问题，而陈岛试图把他接回研究所，认为症状来自被放大的雌蛾求偶讯号。这个解释有调查上的合理性，却没有立刻提供可靠治疗；用另一类信号抵销原影响只是研究方向，可能有效也可能造成其他变化。洪安后来与时造同行接受进一步研究，被提醒不要再到处要求别人看自己手中的蛾，他尴尬地答应，仍未获得确定的康复结论。卡片把他的专业背景、受损经验与想得到理解的愿望放在一起，不把“看见不存在之物”包装成召唤幻蝶、制造幻觉或攻击他人的能力。他可以在新场景中记录自己的感受、同可信伙伴对照事实，同时保留那种眼前明明看见却被所有人否认的困惑，而不是用机械重复一句“有蛾”替代完整人格。','《茫点》返回研究所继续尝试治疗，症状是否消失未定','主角','让别人理解自己的真实体验，找回可以信任的感知','认真描述自己所见，期待研究能够解释异常','别人直接否认时反复展示与争辩，被理解后愿意配合治疗','主观真实不保证客观存在，求治方案也须承认试验性',[ab('蛾类信号研究经验','参与记录和放射生物信号，对研究过程有实际接触','长期接触造成自身症状；不等于能控制所有昆虫'),ab('异常知觉记录','能持续报告所见，作为研究副作用的重要线索','非自主施法，不能把蛾投射给别人')],[ev('058',4150,4155,'症状与同类受害者'),ev('058',4175,4188,'暴露机制与治疗假说'),ev('058',4269,4272,'回所安排'),ev('058',4478,4479,'终局未定')],profile='expert'))
cards.append(compact('ge_ling','葛陵','葛陵是经过严格训练的太空人，隶属美国太空总署，与妻子桃丽感情亲密。接到主驾驶任务前，他长期训练，休假时仍要在重大责任与私人生活间调节；妻子希望他在太空向自己表达爱意，使冷峻的航行任务带着普通人的期待。飞行过程中接触异常讯号后，他的脑部活动受到干扰，返回地球时表现与通常语言和认知不符，仍把飞船安全降落这件事本身便成为难解线索。道吉尔、江楼月和陈岛等人通过信号研究尝试解释并帮助他，后来在研究所接受相关刺激时，他突然恢复正常，却不记得那一段发生过什么，像记忆中被挖去一块。文本以潜意识可能未受误导解释他仍能操作降落，不能由此推出驾驶者失去意识也永远不会出错。终局卡保留本人已经恢复的日常认知、航行训练和那段空白，不赋予外星语言、读心或脑信号控制能力。新的飞行环境中，他可以认真核查仪器与自身状态，也会珍惜同妻子的承诺；受影响经历是知识与创伤，不能机械作为超能觉醒。','《茫点》接受信号处理后恢复正常，但异常期间记忆空白','主角','完成航行责任并回到所爱的人身边，重新理解自己失去的一段经历','受训严格，行动稳健，私下对妻子温柔直接','任务中优先依训练处理仪器，恢复后承认自己并不记得全部经过','专业能力不能免疫未知刺激，恢复也不等于获得刺激来源的知识',[ab('太空驾驶','接受长期航行训练，能够操作飞船并在事件中安全降落','依赖飞船与地面支持，非个人宇宙飞行；异常中降落不能保证可重复'),ab('任务纪律','在重大任务前接受强化训练并注意状态','仍有被信号干扰及失忆的明确弱点')],[ev('058',171,192,'身份、训练与夫妻关系'),ev('058',4288,4295,'安全降落事实'),ev('058',4351,4385,'研究处理'),ev('058',4466,4473,'恢复与记忆空白')],profile='expert',aliases=['葛陵少校']))
cards.append(compact('daojier','道吉尔','道吉尔是研究太空生物的科学家，著作甚多，对陌生生命问题拥有专业声望，也同卫斯理的大胆假设长期互不相让。收集到异常讯号后，他带着分析结果求见卫斯理，显出在真正难题前愿意跨过私人不快的一面；所谓来自太空的声音很快又同人类对话、太空任务和脑部干扰发生关联，让他原本的分类不断受到挑战。面对葛陵的状况，他既焦急又挫败，想从飞行和设备安排中找到解释，但不能单靠重新派出飞船就把问题归零。江楼月负责技术协作，陈岛与梁若水从生物信号和医学方向补充，他需要在几种专业语言之间承认自己的盲区。终局并未宣布他发现一个可直接通讯的外星文明，也没有让他控制那类讯号。他的角色应表现研究者在声望、自尊和对证据的责任间调整，而非只作为卫斯理每次驳倒的靶子。遇到新线索时，他可以坚持测量方法，要求重复验证，也可以在有力反证出现后撤回旧结论，继续做尚未完成的工作。','《茫点》参与异常信号和太空人问题的研究，未取得可控外星通讯或脑控技术','主角','弄清未知信号及生命来源，并维护研究方法的可信度','讲解严密，重视专业声望，对被嘲讽容易生气','数据超出理论时会焦急，仍愿寻求此前意见不合者帮助','权威必须接受新证据，专业词汇不能替代真正解释',[ab('太空生物研究','分析未知信号、组织研究并与航行基地联系','无法仅凭信号证明所有外星假说，更不能把研究设备能力视作个人超能')],[ev('058',624,672,'学术身份和过往争论'),ev('058',730,855,'求助和信号分析'),ev('058',4351,4364,'面对太空人异常')],profile='expert',aliases=['道吉尔博士']))
cards.append(compact('shizao_fangzi','时造芳子','时造芳子与哥哥时造旨人同住在小居所，为让她有独立卧室，哥哥作过生活上的让步，这份关系使她对哥哥的遭遇格外不能接受。她平时有礼，仍会随身带着哥哥的文章，在有人非议时拿出来争论；当尾杉突然上门袭击哥哥，她不是只在一旁哭泣，而是尝试拉开对方，自己被踢倒后又设法救人，终于配合邻人和警察阻止了悲剧。哥哥被送入医院，她远道来探望，焦急询问为什么一个一直正常的人会突然变成病人，也向卫斯理提供文章与当日经过。她对镜中现象的惊惧成为调查线索的一部分，却没有证实她自己能制造或控制异常影像。案件后来牵涉白素，她与弥子陪伴这个受到误控的人，表现出不只围绕自己家人行动的同情。终局哥哥仍在接受研究，她也没有得到保证康复的圆满答案。卡片把家庭忠诚、礼貌与紧急时的勇敢共同保留，不给她哥哥的专业或尾杉的可疑读心能力；她可以继续追问，也应有机会表达等待和不确定给自己带来的疲惫。','《茫点》继续关心哥哥治疗，并陪伴白素度过案件，未发生超常能力转变','主角','保护哥哥并让他的经历获得公平理解','有礼而认真，愿拿出材料为亲近者辩护','亲人受袭时即使害怕也动手救援，对病情不明则主动求助','不能把不理解的体验简单当作故意胡说，仍须让证据接受核查',[ab('亲历证词与资料保存','保存哥哥文章，准确说明来访和袭击经过','证词也受观察范围限制，不自动解释机制'),ab('紧急援助','在袭击现场拉架并配合他人救人','没有专业武术或超常力量证据')],[ev('058',1152,1155,'探病求助'),ev('058',1322,1346,'维护文章与兄妹生活'),ev('058',1376,1427,'袭击中救援'),ev('058',4021,4023,'陪伴白素')],profile='ordinary',aliases=['芳子']))
save(cards)
cover('058',[('卫斯理','wei_sili','主角','调查并以物证救白素'),('白素','bai_su','主角','调查者及被误控者'),('时造旨人','shizao_zhiren','主角','信号干扰受害者'),('时造芳子','shizao_fangzi','主角','救援和提供线索'),('尾杉三郎','weishan_sanlang','反派','袭击与危险设备使用'),('张强','zhang_qiang','主角','医学调查受害'),('梁若水','liang_ruoshui','重要配角','医学研究者'),('陈岛','chen_dao','重要配角','信号研究者'),('高田','gao_tian','主角','刑案合作与物证'),('江楼月','jiang_louyue','主角','电脑研究协作'),('道吉尔','daojier','主角','太空生物研究'),('葛陵','ge_ling','主角','太空任务受影响者'),('洪安','hong_an','主角','研究工作人员受影响者'),('小郭','xiao_guo','重要配角','调查张强职业'),('安普女伯爵','adventure_anpu','重要配角','资助研究机构')],[('桃丽','太空人亲属和开篇生活视角，不独立参与后续核心冲突，不据此扩大为跨书重要配角'),('弥子','酒店一次性帮助者及尾杉情妇，未见跨书身份或独立反派目的'),('宝田满和两名女工','感知受干扰的证人，不是已证实的合谋诬告者'),('弗烈、杰克','仪器制作来源为推断，缺少独立主线行动，记在机制不确定项')],['尾杉读心为不稳定解释；对张强催眠只是推测。受影响人物没有因此得到可控幻觉或隐身。'])
